import{_ as i,C as o,o as s,c,j as e,a as d,E as a,ag as h}from"./chunks/framework.HG0H2VLS.js";const y=JSON.parse('{"title":"SegmentedControl","description":"","frontmatter":{},"headers":[],"relativePath":"components/segmented-control.md","filePath":"components/segmented-control.md"}'),l={name:"components/segmented-control.md"},g={id:"segmentedcontrol",tabindex:"-1"};function m(p,t,f,u,b,x){const n=o("Badge"),r=o("ComponentDemo");return s(),c("div",null,[t[3]||(t[3]=e("hr",null,null,-1)),t[4]||(t[4]=e("h2",{id:"title-segmentedcontrol",tabindex:"-1"},[d("title: SegmentedControl "),e("a",{class:"header-anchor",href:"#title-segmentedcontrol","aria-label":'Permalink to "title: SegmentedControl"'},"​")],-1)),e("h1",g,[t[0]||(t[0]=d("SegmentedControl ",-1)),a(n,{type:"tip",text:"AI Chat"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#segmentedcontrol","aria-label":'Permalink to "SegmentedControl <Badge type="tip" text="AI Chat" />"'},"​",-1))]),t[5]||(t[5]=e("blockquote",null,[e("p",null,"Radio-style toggle")],-1)),a(r,{src:"/demos/src/components/SegmentedControl/SegmentedControl.html"}),t[6]||(t[6]=h('<h2 id="variant-×-size-matrix" tabindex="-1">Variant × Size Matrix <a class="header-anchor" href="#variant-×-size-matrix" aria-label="Permalink to &quot;Variant × Size Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>State</th><th>Size</th><th>Frame</th><th>Built</th></tr></thead><tbody><tr><td><code>2699:2062</code></td><td>Light</td><td>Default</td><td>172×40</td><td>✅ <code>.seg-control</code></td></tr><tr><td><code>2699:2053</code></td><td>Dark</td><td>Default</td><td>172×40</td><td>✅ <code>.seg-control</code></td></tr><tr><td><code>3729:25008</code></td><td>Light</td><td>sm</td><td>146×32</td><td>✅ <code>.seg-control--sm</code></td></tr><tr><td><code>3729:16713</code></td><td>Dark</td><td>sm</td><td>154×32</td><td>✅ <code>.seg-control--sm</code></td></tr></tbody></table><h2 id="what-sm-actually-changes" tabindex="-1">What <code>sm</code> actually changes <a class="header-anchor" href="#what-sm-actually-changes" aria-label="Permalink to &quot;What `sm` actually changes&quot;">​</a></h2><p>Not a scaled-down Default. <strong>Every value on the button is identical</strong> — 32px tall, <code>--ai-spacing-4</code> padding, <code>--ai-spacing-3</code> gap, 16px icon, the same <code>button/sm</code> type ramp. What changes is the <strong>container</strong>, and with it the shape of the whole thing:</p><table tabindex="0"><thead><tr><th></th><th>Default</th><th>sm</th></tr></thead><tbody><tr><td>Container height</td><td><code>--ai-spacing-8</code> (40)</td><td><code>--ai-spacing-7</code> (32)</td></tr><tr><td>Container padding</td><td><code>--ai-spacing-1</code> (4)</td><td><strong>0</strong></td></tr><tr><td>Active segment</td><td>a pill floating inside the box, <code>--ai-radius-sm</code> all round</td><td>flush to the container edge, <code>--ai-radius-md</code> on its <strong>outer corners only</strong></td></tr></tbody></table><p>So the Default reads as a box containing a pill, and <code>sm</code> reads as one joined bar. The corner treatment follows from the padding, not the other way round.</p><p>Corner radii are set <strong>per button</strong> rather than with <code>overflow: hidden</code> on the container: the focus state is a box-shadow ring, and a clipped container would eat it.</p><h2 id="flagged-for-figma" tabindex="-1">Flagged for Figma <a class="header-anchor" href="#flagged-for-figma" aria-label="Permalink to &quot;Flagged for Figma&quot;">​</a></h2><p><strong>1. The two <code>sm</code> variants disagree with each other.</strong> <code>State=Light, Size=sm</code> is <strong>146</strong> wide with its buttons at <code>pl 8 / pr 12</code>; <code>State=Dark, Size=sm</code> is <strong>154</strong> with <code>12</code> both sides, matching the Default. Same control, same size, 8px different depending on which half is active — a toggle that changes width when you press it. Built at <strong>12/12</strong>, which two of the three datapoints agree on.</p><p><strong>2. <s>The active segment&#39;s background does not match the code.</s> RESOLVED 2026-09-22 — and the two Figma sources were each right about a different surface.</strong> The Design System&#39;s ThemeToggle binds <code>--ai-surface-secondary</code>; the code used <code>--ai-surface-minimal</code>, which is what the AI Chat SegmentedControl binds. Resolved per surface, the reason is plain:</p><table tabindex="0"><thead><tr><th>surface</th><th><code>--ai-surface-secondary</code></th><th>container <code>--ai-surface-primary</code></th><th></th></tr></thead><tbody><tr><td>base</td><td><code>#e9eef4</code></td><td><code>#ffffff</code></td><td>✓</td></tr><tr><td>cc</td><td><code>#e7edf0</code></td><td><code>#ffffff</code></td><td>✓</td></tr><tr><td>cc-dark</td><td><code>#3d4b5f</code></td><td><code>#1e293b</code></td><td>✓</td></tr><tr><td><strong>chat</strong></td><td><strong><code>#ffffff</code></strong></td><td><code>#ffffff</code></td><td>✗ invisible</td></tr><tr><td>chat-dark</td><td><code>#2e2e32</code></td><td><code>#212123</code></td><td>✓</td></tr></tbody></table><p>So <code>secondary</code> is now the rule, per the designer, and a <code>[data-surface=&quot;chat&quot;]</code> guard keeps <code>minimal</code> on the one surface where <code>secondary</code> would make the active segment disappear into its own container — which is the surface this component&#39;s own demo page runs as. Both bindings kept, each where it is correct. Verified in all four combinations.</p><p><strong>2b. The divider.</strong> <code>sm</code> only: a 1px <code>--ai-border-secondary</code> on the ACTIVE segment&#39;s inner edge — its right when the left half is active, its left when the right half is (designer, 2026-09-22). Not in either Figma. The Default keeps 4px of container padding so its segments never touch, and a line between them would float in the gap; <code>sm</code> has none, so without a divider the bar reads as a box with a shaded end rather than two joined halves. On the active segment rather than always on the first button so it sits over the fill and stays a crisp 1px instead of being a seam between two backgrounds.</p><p><strong>3. The duplication with ThemeToggle</strong>, above.</p><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code></td><td>container background</td><td></td></tr><tr><td><code>--ai-border-secondary</code></td><td>container border</td><td>1px</td></tr><tr><td><code>--ai-radius-md</code></td><td>container radius, and the sm active segment&#39;s outer corners</td><td></td></tr><tr><td><code>--ai-spacing-8</code> / <code>--ai-spacing-7</code></td><td>container height, Default / sm</td><td></td></tr><tr><td><code>--ai-spacing-1</code> / <code>0</code></td><td>container padding, Default / sm</td><td></td></tr><tr><td><code>--ai-spacing-7</code></td><td>button height (both sizes)</td><td>was a hardcoded <code>32px</code>; fixed 2026-09-22</td></tr><tr><td><code>--ai-spacing-4</code></td><td>button padding-inline (both sizes)</td><td></td></tr><tr><td><code>--ai-spacing-3</code></td><td>icon-to-label gap (both sizes)</td><td></td></tr><tr><td><code>--ai-icon-size-sm</code></td><td>icon, 16px (both sizes)</td><td></td></tr><tr><td><code>button/sm</code></td><td><code>--ai-font-body</code> · <code>--ai-font-semibold</code> · <code>--ai-font-fluid-xxs</code> · <code>--ai-leading-xs</code></td><td>identical on both sizes</td></tr><tr><td><code>--ai-btn-tertiary-text</code></td><td>active label</td><td></td></tr><tr><td><code>--ai-btn-secondary-text-hover</code></td><td>inactive label</td><td></td></tr></tbody></table><h2 id="token-gaps" tabindex="-1">Token Gaps <a class="header-anchor" href="#token-gaps" aria-label="Permalink to &quot;Token Gaps&quot;">​</a></h2><p>None. Every value traces to an <code>--ai-*</code> token.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Icons in Figma are named <code>Icon/24px/Sun</code> and <code>Icon/24px/Moon</code> but placed at <strong>16px</strong> — the design context reports the component&#39;s intrinsic size, not the placed size. Lucide <code>sun</code> / <code>moon</code>.</li><li>Each button carries a hidden <code>Icon/20px/PanelLeft</code> instance in all four variants. Unused; not built.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Ikv8jxb5dcRH8ff4q4dR11/Affino-AI---AI-Chat?node-id=2162-5079" target="_blank" rel="noreferrer">Open in Figma</a></p>',22))])}const k=i(l,[["render",m]]);export{y as __pageData,k as default};
